// Files generated by the editor; these are not treated as declaring blocks
const generatedFiles = [
    pxt.MAIN_TS,
    pxt.TUTORIAL_CODE_START,
    pxt.TUTORIAL_CODE_STOP,
    pxt.TILEMAP_CODE,
    pxt.IMAGES_CODE
];

/**
 * Returns true if the project has a TypeScript file other than the generated files, either at the top level
 * or in a folder. Such a file could export blocks, so the cached API info cannot be used. Files under
 * pxt_modules belong to dependencies, whose API info is looked up separately.
 */
export function projectMayDeclareBlocks(filenames: string[]): boolean {
    return filenames.some(
        filename => generatedFiles.indexOf(filename) === -1
            && !pxt.Util.startsWith(filename, "pxt_modules/")
            && pxt.Util.endsWith(filename, ".ts")
    );
}
